const configured = String($env.PROSPECTING_QUERIES || '').split(',').map((value) => value.trim()).filter(Boolean);
const queries = configured.length ? configured : [
  '"diagramação editorial" orçamento',
  '"projeto editorial" livro editora',
  '"relatório anual" diagramação',
  '"catálogo" diagramação design editorial',
  '"publicação" "projeto gráfico"',
  '"livro" "projeto gráfico" contratar'
];
return queries.slice(0, 10).map((query) => ({ json: { query } }));

const emailPattern = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
const blockedHosts = new Set(['google.com', 'facebook.com', 'instagram.com', 'linkedin.com', 'youtube.com', 'tiktok.com']);
const terms = ['diagramação', 'diagramacao', 'editorial', 'livro', 'catálogo', 'catalogo', 'relatório anual', 'relatorio anual', 'revista', 'publicação', 'publicacao', 'editora', 'projeto gráfico', 'projeto grafico', 'orçamento', 'orcamento', 'contratar'];
const opportunities = [];

for (const item of $input.all()) {
  const results = Array.isArray(item.json.items) ? item.json.items : [];
  for (const result of results) {
    const link = String(result.link || '').trim();
    let parsed;
    try { parsed = new URL(link); } catch { continue; }
    if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password) continue;
    const host = parsed.hostname.replace(/^www\./, '').toLowerCase();
    if (!host || blockedHosts.has(host) || [...blockedHosts].some((blocked) => host.endsWith('.' + blocked))) continue;
    const title = String(result.title || '').replace(/\s+/g, ' ').trim();
    const snippet = String(result.snippet || result.htmlSnippet || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    const evidence = [title, snippet].filter(Boolean).join(' — ').slice(0, 700);
    const searchable = evidence.toLocaleLowerCase('pt-BR');
    const matchedTerms = terms.filter((term) => searchable.includes(term));
    const emails = [...new Set((evidence.match(emailPattern) || []).map((email) => email.toLowerCase()))];
    const score = Math.min(100, matchedTerms.length * 15 + (emails.length ? 10 : 0) + (/(contratar|orçamento|orcamento|proposta|briefing|serviço|servico)/i.test(searchable) ? 20 : 0));
    if (matchedTerms.length < 2 || score < 30) continue;
    const normalizedUrl = parsed.origin + parsed.pathname.replace(/\/$/, '');
    opportunities.push({
      json: {
        prospect_key: (emails[0] || host).toLowerCase(),
        prospect_name: title || host,
        prospect_email: emails[0] || '',
        prospect_url: normalizedUrl,
        source_url: normalizedUrl,
        evidence: evidence,
        matched_terms: matchedTerms,
        relevance_score: score
      }
    });
  }
}
const unique = new Map();
for (const item of opportunities) {
  const previous = unique.get(item.json.prospect_key);
  if (!previous || item.json.relevance_score > previous.json.relevance_score) unique.set(item.json.prospect_key, item);
}
return [...unique.values()].sort((a, b) => b.json.relevance_score - a.json.relevance_score);

const candidates = $items('Validar e qualificar oportunidades').map((item) => item.json);
const processed = $items('Buscar contatos processados hoje').map((item) => item.json);
const processedText = processed.map((item) => JSON.stringify(item).toLowerCase()).join('\n');
const suppression = new Set(String($env.SUPPRESSION_EMAILS || '').split(',').map((value) => value.trim().toLowerCase()).filter(Boolean));
const configuredLimit = Number($env.PROSPECTING_DAILY_LIMIT || 10);
const dailyCount = processed.length;
const remaining = Math.max(0, Math.min(configuredLimit, configuredLimit - dailyCount));
const portfolioUrl = String($env.PORTFOLIO_URL || '').trim();
const landingUrl = String($env.LANDING_PAGE_URL || '').trim();
const validReference = (value) => { try { const url = new URL(value); return ['http:', 'https:'].includes(url.protocol) && !url.username && !url.password; } catch { return false; } };
const validPortfolio = validReference(portfolioUrl) ? portfolioUrl : '';
const validLanding = validReference(landingUrl) ? landingUrl : '';

return candidates.map((candidate) => {
  const email = String(candidate.prospect_email || '').trim().toLowerCase();
  const key = String(candidate.prospect_key || '').toLowerCase();
  const alreadyProcessed = Boolean((email && processedText.includes(email)) || (key && processedText.includes(key)) || processedText.includes(String(candidate.source_url || '').toLowerCase()));
  const suppressed = Boolean(email && suppression.has(email));
  const recipient = candidate.prospect_name || 'equipe';
  const marker = `[PROSPECCAO-EDITORIAL:${key}]`;
  const subject = `${marker} Uma ideia para o projeto editorial de ${recipient}`;
  const body = [`Olá, ${recipient}!`, '', 'Encontrei uma referência pública que indica um possível projeto editorial e achei que meu trabalho poderia contribuir na próxima etapa.', '', `Evidência encontrada: ${candidate.evidence}`, `Fonte pública: ${candidate.source_url}`, '', 'Trabalho com direção de arte, projeto gráfico e diagramação editorial, com atenção à clareza, consistência visual e preparação dos arquivos finais.', validPortfolio ? `Portfólio: ${validPortfolio}` : '', validLanding ? `Landing page de diagramação editorial: ${validLanding}` : '', '', 'Se houver um briefing em andamento, posso avaliar o escopo e compartilhar uma proposta adequada. Caso não seja relevante, basta responder solicitando não contato.', '', 'Abraços,', 'Rayssa Martins'].filter(Boolean).join('\n');
  const eligible = Boolean(email && !alreadyProcessed && !suppressed && validPortfolio && validLanding);
  return { json: { ...candidate, prospect_email: email, prospect_subject: subject, prospect_body: body, evidence_url: candidate.source_url, already_processed: alreadyProcessed, suppressed, references_valid: Boolean(validPortfolio && validLanding), action: eligible ? 'draft' : 'skip', skip_reason: !email ? 'sem_email_publico' : alreadyProcessed ? 'duplicado' : suppressed ? 'suprimido' : !validPortfolio || !validLanding ? 'urls_de_referencia_invalidas_ou_ausentes' : '' } };
}).filter(({ json }) => json.action === 'draft').slice(0, remaining);
